  5	namespace Application\Bootstrap\Screen;
  6	
  7	use Application\Application;
  8	use Application\AppFactory;
  9	use Application\Bootstrap\BootException;
 10	use Application\ConfigSettings\BaseConfigRegistry;
 11	use Application_Bootstrap_Screen;
 12	use AppUtils\FileHelper;
 13	use DBHelper;
 14	
 15	class TestSuiteBootstrap extends Application_Bootstrap_Screen
 16	{
 17	    public const int ERROR_TEST_DB_NOT_SEEDED = 175001;
 18	
 19	    protected function _boot() : void
 20	    {
 21	        $this->disableAuthentication();
 22	        $this->enableScriptMode();
 23	
 24	        $this->createEnvironment();
 25	
 26	        if (!defined('APP_TESTS_RUNNING')) {
 27	            define('APP_TESTS_RUNNING', true);
 28	        }
 29	
 30	        $this->configureDatabase();
 31	        $this->registerTransactionCleanupHandler();
 32	        $this->configurePaths();
 33	        $this->configureUsers();
 34	    }
 35	
 36	    private function configureDatabase(): void
 37	    {
 38	        $port = 0;
 39	
 40	        if (defined('APP_DB_TESTS_PORT')) {
 41	            $port = (int)APP_DB_TESTS_PORT;
 42	        }
 43	
 44	        DBHelper::registerDB(
 45	            'tests',
 46	            APP_DB_TESTS_NAME,
 47	            APP_DB_TESTS_USER,
 48	            APP_DB_TESTS_PASSWORD,
 49	            APP_DB_TESTS_HOST,
 50	            $port
 51	        );
 52	
 53	        DBHelper::selectDB('tests');
 54	    }
 55	
 56	    private function configureUsers(): void
 57	    {
 58	        $users = AppFactory::createUsers();
 59	        $missingIDs = array();
 60	
 61	        foreach(Application::getSystemUserIDs() as $id)
 62	        {
 63	            if(!$users->idExists($id))
 64	            {
 65	                $missingIDs[] = $id;
 66	            }
 67	        }
 68	
 69	        if(!empty($missingIDs))
 70	        {
 71	            throw new BootException(
 72	                'Test database not seeded: system user(s) missing.',
 73	                sprintf(
 74	                    'The following system user IDs are missing from the test database: [%s]. '.
 75	                    'Run "composer seed-tests" to initialize the test environment.',
 76	                    implode(', ', $missingIDs)
 77	                ),
 78	                self::ERROR_TEST_DB_NOT_SEEDED
 79	            );
 80	        }
 81	
 82	        $this->log('System users verified.');
 83	    }
 84	
 85	    public static function seedSystemUsers(): void
 86	    {
 87	        DBHelper::startTransaction();
 88	
 89	        try
 90	        {
 91	            Application::createInstaller()
 92	                ->getTaskByID('InitSystemUsers')
 93	                ->process();
 94	
 95	            DBHelper::commitTransaction();
 96	        }
 97	        catch(\Throwable $e)
 98	        {
 99	            DBHelper::rollbackConditional();
100	            throw $e;

101	        }
102	    }
103	
104	    private function registerTransactionCleanupHandler(): void
105	    {
106	        register_shutdown_function(static function(): void {
107	            DBHelper::rollbackConditional();
108	        });
109	    }
110	
111	    private function configurePaths(): void
112	    {
113	        $testsRoot = APP_ROOT . '/tests';
114	
115	        if (BaseConfigRegistry::areUnitTestsRunning()) {
116	            $testsRoot = APP_ROOT;
117	        }
118	
119	        if (!is_dir($testsRoot)) {
120	            die('Cannot run tests: Could not find the application\'s [tests] folder.');
121	        }
122	
123	        define('TESTS_ASSETS_FOLDER', TESTS_ROOT . '/assets');
124	        define('TESTS_CLASSES_FOLDER', TESTS_ASSETS_FOLDER . '/classes');
125	
126	        if (is_dir(TESTS_CLASSES_FOLDER)) {
127	            $names = FileHelper::createFileFinder(TESTS_CLASSES_FOLDER)
128	                ->getPHPClassNames();
129	
130	            // load all classes that may be needed for the tests to run.
131	            foreach ($names as $name) {
132	                require_once TESTS_CLASSES_FOLDER . '/' . $name . '.php';
133	            }
134	        }
135	    }
136	
137	    public function getDispatcher() : string
138	    {
139	        return 'bootstrap.php';
140	    }
141	}

